TERM_BY_SLUG = {t['slug']: t for t in TERMS}


def check(doc_ids):
    seen = set()
    for t in TERMS:
        assert re.fullmatch(r'[a-z0-9-]+', t['slug']) and t['slug'] not in seen, t['slug']
        seen.add(t['slug'])
        for k in ('term', 'plain', 'where'): assert t.get(k), f'{t["slug"]}: немає {k}'
        for d in t['docs']: assert d in doc_ids, f'{t["slug"]}: невідомий документ {d}'
        if t.get('src'): assert t['src'][1].startswith('https://zakon.rada.gov.ua/laws/show/'), t['slug']
